export type ParsedApplyAsIntegratorInstruction<
  TProgram extends string = typeof PACTUM_CORE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    integratorApplication: TAccountMetas[0];
    marketplace: TAccountMetas[1];
    globalConfig: TAccountMetas[2];
    identity?: TAccountMetas[3] | undefined;
    sasKybAttestation?: TAccountMetas[4] | undefined;
    sasCredential?: TAccountMetas[5] | undefined;
    authority: TAccountMetas[6];
    payer: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
  };
  data: ApplyAsIntegratorInstructionData;
};

export function parseApplyAsIntegratorInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedApplyAsIntegratorInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === PACTUM_CORE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      integratorApplication: getNextAccount(),
      marketplace: getNextAccount(),
      globalConfig: getNextAccount(),
      identity: getNextOptionalAccount(),
      sasKybAttestation: getNextOptionalAccount(),
      sasCredential: getNextOptionalAccount(),
      authority: getNextAccount(),
      payer: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getApplyAsIntegratorInstructionDataDecoder().decode(instruction.data),
  };
}
